function capitalize(s) { return s.charAt(0).toUpperCase() + s.slice(1); }
function slugify(t) { return t.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, ''); }
module.exports = { capitalize, slugify };

add-cache.math.js:
let calls = 0;
function slowSquare(n) { calls++; return n * n; }
function callCount() { return calls; }
const memo = new Map();
function fastSquare(n) { if (!memo.has(n)) memo.set(n, slowSquare(n)); return memo.get(n); }
module.exports = { slowSquare, callCount, fastSquare };

